# session's invoke_subagent, extracts the verdict packet JSON, prints on stdout.
set -euo pipefail
REQ=$(cat)
SCRATCH="${SCRATCH_DIR:-/home/sleeg/work/native-gravity-evidence/44g/g3-live/scratch}"
# steamroller primary invokes zen via invoke_subagent; the request JSON is the task
PROMPT="Use invoke_subagent to call 'zen' with this exact task (pass it verbatim): $REQ

Report zen's response verbatim — the full JSON verdict packet it returns."
RESP=$(cd "$SCRATCH" && timeout 600 agy --agent steamroller --model gemini-3.1-pro-low --output-format json --print "$PROMPT" 2>/dev/null)
# save raw response for debugging
echo "$RESP" > "${SCRATCH_DIR:-/tmp}/zen-raw-$(date +%s%N).json"
# extract the verdict JSON object from the response
echo "$RESP" | node -e '
let d="";process.stdin.on("data",c=>d+=c).on("end",()=>{
  try{const j=JSON.parse(d);const r=j.response||"";
    // find the verdict JSON: look for an object containing "verdict"
    const m=r.match(/\{[^{}]*"verdict"[^{}]*"verification_evidence"[\s\S]*?\][\s\S]*?\}/);
    if(m){process.stdout.write(m[0])}
    else{const m2=r.match(/\{[\s\S]*"verdict"[\s\S]*\}/);process.stdout.write(m2?m2[0]:JSON.stringify({verdict:"NO-GO",milestone_id:"unknown",plan_version:"unknown",result_ref:"unknown",verification_evidence:[{classification:"INFERRED",criterion:"parse",result:"no verdict JSON in zen response: "+r.slice(0,300)}]}))}
  }catch(e){process.stdout.write(JSON.stringify({verdict:"NO-GO",milestone_id:"unknown",plan_version:"unknown",result_ref:"unknown",verification_evidence:[{classification:"INFERRED",criterion:"parse",result:"unparseable: "+String(e).slice(0,200)}]}))}
});'
